"""The root requirements.txt must be a fresh export of uv.lock (no network, no installs)."""

import shutil
import subprocess
from pathlib import Path

import pytest

pytestmark = pytest.mark.cpu

ROOT = Path(__file__).resolve().parents[1]
EXPORT_ARGS = [
    "--frozen",
    "--no-hashes",
    "--no-dev",
    "--emit-index-url",
    "--format",
    "requirements-txt",
]
HEADER_PREFIX = "# This file was autogenerated by uv"


def body(text: str) -> list[str]:
    """Drop the autogenerated header: it records the exact command line, which legitimately
    differs between the committed file (`-o requirements.txt`) and a temp-file export."""
    lines = text.splitlines()
    if lines and lines[0].startswith(HEADER_PREFIX):
        lines = lines[1:]
        while lines and lines[0].startswith("#"):
            lines = lines[1:]
    return lines


@pytest.fixture(scope="module")
def fresh_export(tmp_path_factory) -> str:
    uv = shutil.which("uv")
    if uv is None:
        pytest.skip("uv is not on PATH; cannot export from uv.lock")
    out = tmp_path_factory.mktemp("export") / "requirements.txt"
    subprocess.run(
        [uv, "export", *EXPORT_ARGS, "-o", str(out)], cwd=ROOT, check=True, capture_output=True
    )
    return out.read_text()


def test_committed_requirements_match_fresh_export(fresh_export):
    committed = (ROOT / "requirements.txt").read_text()
    assert body(committed) == body(fresh_export), (
        "requirements.txt is stale. Regenerate: uv export --frozen --no-hashes --no-dev "
        "--emit-index-url --format requirements-txt -o requirements.txt"
    )


def test_export_keeps_cuda_index_and_local_package_and_omits_cuda_kernels(fresh_export):
    lines = fresh_export.splitlines()
    assert "--extra-index-url https://download.pytorch.org/whl/cu134" in lines
    assert "./infrastructure/extension/ipykernel_pipe_fix" in lines
    lowered = fresh_export.lower()
    for name in ("causal-conv1d", "mamba-ssm"):
        assert name not in lowered


def test_other_requirements_files_are_not_exports():
    for name in ("requirements-original.txt", "requirements-ci-cpu.txt"):
        path = ROOT / name
        assert path.is_file(), f"{name} must be kept"
        assert not path.read_text().startswith(HEADER_PREFIX), f"{name} must not be a uv export"
